	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		System_
	 */
		public System_ createSystem_( CreateSystem_Command command ) {

		System_ entity = new System_();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setSystem_Id( command.getSystem_Id() );
            entity.setName( command.getName() );
            entity.setOwnerDepartment( command.getOwnerDepartment() );
            entity.setSystemType( command.getSystemType() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of System_ {0} ", entity.toString() );

		return entity;
	}

